(() => {
  'use strict';
  const S=window.HangeoreumSpending;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const won=v=>v.toLocaleString('ko-KR')+'원';
  const variance=v=>v===null?'판단 보류':v>0?won(v)+' 초과':v<0?won(-v)+' 절감':'예상과 같음';
  function mount(host,raw,estimate,plan,onChange) {
    let a;try{a=S.analyze(raw);}catch(e){host.innerHTML='<section class="spending-panel"><h2>실제 지출</h2><p role="alert">'+esc(e.message)+'</p></section>';return;}
    const s=a.state,b=s.baseline;
    host.innerHTML=`<section class="spending-panel" aria-label="예산 대비 실제 지출"><details ${raw?'open':''}><summary>여행 후 · 실제 지출 기록과 분석</summary><p>현지 하루 식비·카페·교통·입장료를 <strong>일행 전체 결제 금액</strong>으로 기록하세요. 왕복 이동·숙박·쇼핑은 제외합니다.</p><p class="small">이 기기의 계획에 저장됩니다. 다른 계획을 열기 전 ‘계획 저장’을 눌러 주세요. 파일 내보내기에도 지출 기록과 이유가 포함됩니다.</p>
    <div class="spending-baseline"><h3>비교 기준</h3>${b?`<p>${esc(b.date)} · ${esc(b.title)} · ${b.people}명<br>예상 ${won(a.planned)}${a.unknown?' + 미확인 '+a.unknown+'건':''} · 총예산 ${b.cap===null?'미입력':won(b.cap)}</p><p class="small">${esc(Number.isFinite(Date.parse(b.savedAt))?new Date(b.savedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):b.savedAt)} 저장. 일정이나 가격을 수정해도 이 기준은 바뀌지 않습니다.${b.date!==plan.date?' 현재 계획 날짜와 다릅니다.':''}</p>`:'<p>예산 비교를 켜고 예상 비용을 확인한 뒤 기준을 저장하세요. 지출만 먼저 기록해도 됩니다.</p>'}<button type="button" class="btn btn-outline btn-sm" data-spending-baseline ${estimate?'':'disabled'}>${b?'현재 예상 비용으로 기준 교체':'현재 예상 비용을 비교 기준으로 저장'}</button><div data-spending-confirm></div></div>
    <h3>지출 입력</h3><form data-spending-form><div class="budget-fields"><label>항목<select class="text-field" name="category">${Object.entries(S.groups).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>지출 내용<input class="text-field" name="label" maxlength="80" required placeholder="예: 점심, 카페, 택시"></label><label>일행 전체 금액 (원)<input class="text-field" name="amount" type="number" min="0" max="100000000" step="1" required inputmode="numeric"></label><label>이유·메모 (선택)<input class="text-field" name="reason" maxlength="300" placeholder="예: 비가 와서 택시 이용"></label></div><button class="btn btn-primary btn-sm" type="submit" data-spending-submit>지출 추가</button> <button class="btn btn-outline btn-sm" type="button" data-spending-cancel hidden>수정 취소</button><p role="status" data-spending-error></p></form>
    <h3>기록한 지출</h3><div class="spending-list">${s.entries.length?s.entries.map((e,i)=>`<div class="budget-line"><strong>${esc(e.label)} · ${won(e.amount)}</strong><p>${S.groups[e.category]} · ${esc(e.reason||'이유 미입력')}</p><button class="btn btn-outline btn-sm" type="button" data-spending-edit="${i}">수정</button> <button class="btn btn-outline btn-sm" type="button" data-spending-delete="${i}">삭제</button><div data-spending-delete-confirm="${i}"></div></div>`).join(''):'<p>아직 기록한 지출이 없습니다. 미입력을 실제 0원으로 확정하지 않습니다.</p>'}</div>
    <label class="check-line"><input type="checkbox" data-spending-complete ${s.complete?'checked':''}> 이 여행의 지출 입력을 모두 마쳤습니다 (지출 없는 항목은 0원)</label><p class="small">추가·수정·삭제하면 입력 중으로 돌아갑니다. 입력 완료는 본인이 확인한 상태입니다.</p>
    <div class="budget-summary"><h3>${s.complete?'입력 완료한 실제 지출':'현재까지 기록한 지출'}</h3><strong data-spending-total>${won(a.actual)}</strong></div><p data-spending-status>${a.remaining===null?'총예산 기준 미설정':a.remaining<0?'총예산 '+won(-a.remaining)+' 초과':s.complete?'총예산 잔액 '+won(a.remaining):'현재 총예산 잔액 '+won(a.remaining)+' · 입력 중, 절감 확정 아님'}</p>
    <div class="spending-table-wrap"><table><caption>항목별 예상 비용과 실제 지출 비교</caption><thead><tr><th>항목</th><th>저장한 예상</th><th>${s.complete?'실제':'기록액'}</th><th>차이</th></tr></thead><tbody>${a.rows.map(r=>`<tr><th>${S.groups[r.key]}</th><td>${r.planned===null?'기준 없음':won(r.planned)+(r.unknown?' + 미확인':'')}</td><td>${won(r.actual)}</td><td>${variance(r.variance)}</td></tr>`).join('')}</tbody></table></div>
    <p data-spending-variance>예상 합계 대비: ${variance(a.variance)}${!s.complete?' · 지출 입력 중':a.unknown?' · 예상 비용 미확인 항목 있음':''}</p><h3>차이를 돌아보기</h3><p class="small">금액 차이는 실제−예상으로 계산합니다. 총예산 잔액과 예상 대비 절감액은 다른 값입니다. 이유는 입력한 메모이며 자동으로 추정한 원인이 아닙니다.</p>${a.rows.filter(r=>r.variance!==null&&r.variance!==0).map(r=>`<p><strong>${S.groups[r.key]} ${variance(r.variance)}</strong> · 입력한 이유: ${esc(r.entries.filter(e=>e.reason).map(e=>e.label+': '+e.reason).join(' / ')||'미입력 — 방문 취소·수량·가격 변동 여부를 확인해 주세요.')}</p>`).join('')}</details></section>`;
    const form=host.querySelector('form'),error=host.querySelector('[data-spending-error]');let editing=null;
    const commit=value=>{onChange(value);};
    host.querySelector('[data-spending-baseline]').onclick=()=>{
      const save=()=>{try{commit({...s,baseline:S.capture(estimate,plan)});}catch(e){error.textContent=e.message;}};
      if(!b){save();return;}
      const c=host.querySelector('[data-spending-confirm]');c.innerHTML='<p>기존 비교 기준이 바뀝니다. 지출 기록은 유지됩니다.</p><button type="button" class="btn btn-outline btn-sm" data-confirm-baseline>기준 교체 확인</button> <button type="button" class="btn btn-outline btn-sm" data-cancel-baseline>취소</button>';c.querySelector('[data-confirm-baseline]').onclick=save;c.querySelector('[data-cancel-baseline]').onclick=()=>c.replaceChildren();
    };
    form.onsubmit=event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(form));commit(S.put(s,S.entry(values,editing??crypto.randomUUID())));}catch(e){error.textContent=e.message;}};
    host.querySelectorAll('[data-spending-edit]').forEach(button=>button.onclick=()=>{const e=s.entries[Number(button.dataset.spendingEdit)];editing=e.id;for(const k of ['category','label','amount','reason'])form.elements[k].value=e[k];host.querySelector('[data-spending-submit]').textContent='수정 저장';host.querySelector('[data-spending-cancel]').hidden=false;form.elements.label.focus();});
    host.querySelector('[data-spending-cancel]').onclick=()=>{editing=null;form.reset();host.querySelector('[data-spending-submit]').textContent='지출 추가';host.querySelector('[data-spending-cancel]').hidden=true;};
    host.querySelectorAll('[data-spending-delete]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.spendingDelete),c=host.querySelector(`[data-spending-delete-confirm="${i}"]`);c.innerHTML='<p>이 지출 기록을 삭제할까요?</p><button type="button" class="btn btn-outline btn-sm" data-confirm-delete>삭제 확인</button> <button type="button" class="btn btn-outline btn-sm" data-cancel-delete>취소</button>';c.querySelector('[data-confirm-delete]').onclick=()=>commit(S.remove(s,s.entries[i].id));c.querySelector('[data-cancel-delete]').onclick=()=>c.replaceChildren();});
    host.querySelector('[data-spending-complete]').onchange=e=>commit({...s,complete:e.target.checked});
  }
  window.HangeoreumSpendingUI={mount};
})();
